import{z as A,x as l,o as t,c as d,q as n,j as o,D as r,d as e,s as i,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Gray 事务","description":"","frontmatter":{"title":"Gray 事务","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gray-transactions.md","filePath":"cs/gray-transactions.md","lastUpdated":1791413859000}'),p={name:"cs/gray-transactions.md"};function c(C,a,h,m,D,f){const s=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="gray-事务" tabindex="-1">Gray 事务 <a class="header-anchor" href="#gray-事务" aria-label="Permalink to &quot;Gray 事务&quot;">​</a></h1><div class="epigraph"><p>把一组读写收成原子、可恢复的单位；失败则像没发生，成功则持久——事务是系统概念，不是 SQL 方言。</p><footer>—— Gray, The Transaction Concept: Virtues and Limitations, 1981；对照 Notes on Database Operating Systems, 1978</footer></div><p><a href="/cs/codd-relational">上一课</a>附录对照了 1970 年关系与数据独立性。附录对照，不插入主干。主干已在<a href="/cs/acid">ACID</a>、<a href="/cs/wal">WAL</a>、<a href="/cs/two-pc">两阶段提交</a>里用过事务规格与日志；这里对照 <strong>Gray 原文的问题</strong>：共享数据上的并发与故障如何用事务收口，以及 2PC 的阻塞限制。不重做 ARIES 三阶段——那是 Mohan 1992。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Codd 给出关系与完整性，不管崩溃与交错。Gray 的缺口是：把「一次业务」做成全有或全无，用日志与锁（或等价物）同时服务并发与恢复。1981 文写美德与限度：长事务、嵌套、分布式投票会卡住。主干把 ACID 四字母放在检查点之后上课，物理上先 WAL 后规格；附录对照概念从哪篇工程传统来。</p><p><span class="marginnote">Haerder and Reuter 1983 把 ACID 缩写写开。Gray and Reuter 后来的书是教材级展开。不要把 ARIES 作者名单写回 1981。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事务：begin 到 commit/abort。恢复：先写日志。<span class="marginnote">为什么「先写日志」：改数据页是随机 I/O 且可能改到一半断电；日志是顺序追加、每条很小。先把日志落盘再动数据页，崩溃后重放日志就能「重做已提交、撤销未提交」——用顺序写的成本买随机写的安全。</span>并发：锁或版本，目标是可串行或可恢复调度。分布式：2PC 的准备与决策，协调器日志是支点——主干 2PC 课已取用 Lampson/Sturgis 与 Gray 这一线。限度：投票阶段阻塞、启发式决策。<span class="marginnote">常见误区：以为两阶段提交「解决」了分布式故障。它只保证要么都提交、要么都不提交，代价是协调器在投票后宕机时，所有参与者抱着已准备的数据干等——这正是「投票阶段阻塞」；生产系统靠协调器备份或超时后的启发式决策缓解。</span></p>',8)),(t(),o(B,null,{default:r(()=>[i(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNIT%5B%22%E4%BA%8B%E5%8A%A1%E5%8D%95%E4%BD%8D%22%5D%20--%3E%20LOG%5B%22%E6%97%A5%E5%BF%97%E6%81%A2%E5%A4%8D%22%5D%0A%20%20UNIT%20--%3E%20ISO%5B%22%E5%B9%B6%E5%8F%91%E9%9A%94%E7%A6%BB%22%5D%0A%20%20UNIT%20--%3E%20TPC%5B%222PC%20%E9%99%90%E5%BA%A6%22%5D%0A%20%20LOG%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20WAL%20%2F%20ACID%20%2F%202PC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("事务把"),E("a",{href:"/cs/buffer-dirty"},"缓冲与脏页"),e(" 的不一致收成可命名的提交点。关系模型提供对象，Gray 提供对象上的故障与并发合同。后文 Diffie–Hellman 换栏到公钥，与提交无关。")],-1)),(t(),o(B,null,{default:r(()=>[i(s,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEGIN%5B%22begin%EF%BC%9A%E8%AE%B0%E5%BD%95%E8%B5%B7%E7%82%B9%22%5D%20--%3E%20OPS%5B%22%E8%AF%BB%E5%86%99%E7%BC%93%E5%86%B2%E9%A1%B5%EF%BC%9A%E6%9C%AA%E5%AE%9A%E7%8A%B6%E6%80%81%22%5D%0A%20%20OPS%20--%3E%20DEC%7B%22%E6%89%A7%E8%A1%8C%E5%88%B0%E5%BA%95%EF%BC%9F%22%7D%0A%20%20DEC%20--%3E%7C%22%E5%85%A8%E9%83%A8%E6%88%90%E5%8A%9F%22%7C%20COMMIT%5B%22commit%EF%BC%9A%E6%97%A5%E5%BF%97%E8%90%BD%E7%9B%98%EF%BC%8C%E6%9B%B4%E6%94%B9%E6%B0%B8%E4%B9%85%22%5D%0A%20%20DEC%20--%3E%7C%22%E4%B8%AD%E9%80%94%E5%A4%B1%E8%B4%A5%22%7C%20ABORT%5B%22abort%EF%BC%9A%E6%8C%89%E6%97%A5%E5%BF%97%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20COMMIT%20--%3E%20P%5B%22%E6%8C%81%E4%B9%85%EF%BC%9A%E5%B4%A9%E6%BA%83%E5%90%8E%E9%87%8D%E6%94%BE%E6%97%A5%E5%BF%97%E9%87%8D%E5%81%9A%22%5D%0A%20%20ABORT%20--%3E%20N%5B%22%E5%83%8F%E6%B2%A1%E5%8F%91%E7%94%9F%EF%BC%9A%E5%85%B6%E4%BB%96%E4%BA%8B%E5%8A%A1%E7%9C%8B%E4%B8%8D%E5%88%B0%E7%97%95%E8%BF%B9%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">直觉类比「全有或全无」：转账是从 A 扣 100、给 B 加 100 两步写。没有事务时若扣完就断电，100 元凭空蒸发；事务保证两步要么都发生、要么都没发生——崩溃恢复时按日志把半成品抹掉或补齐。</span></p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干数据库从套接字缺口进入关系，物理页与 WAL 在代数之后。把 1981 插在 Codd 之后当「下一课」，会跳过键、SQL 与计划。附录只对照事务作为系统概念的出处，不改变课序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1981 概念文与 1992 ARIES 实现文混成一篇。也不要在附录里开 Saga 补偿的全部语义。下一篇对照 Diffie–Hellman 1976。</p><p>对照结束应回到主干<a href="/cs/acid">ACID</a>与<a href="/cs/wal">WAL</a>。Gray 不插入 SQL 课之前。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Gray：事务是原子可恢复单位，2PC 有限度。</li><li>主干 ACID/WAL/2PC 已取用；ARIES 是后一篇实现传统。</li><li>出处：Gray 1981；对照 1978 Notes；Haerder and Reuter 1983 缩写。</li></ul>',8))])}const _=A(p,[["render",c]]);export{T as __pageData,_ as default};
